contract InvMutTest {
    C c;
    address payable selfPayable;

    constructor(C _c) payable {
        c = _c;
        selfPayable = payable(address(this));
    }

    // single public entry that the checker will call with arbitrary inputs
    function run(uint256 artId, uint256 sendValue) public payable {
        require(address(this).balance >= sendValue, "need funds for forwarding");
        // read pre-state
        uint256 beforeCounter = c.tokenIdCounter();
        // the mapping from artId should be 0 before creation for a fresh artId
        uint256 beforeMapped = c.getTokenIdFromFactoryArtId(artId);

        // call createArtFromFactory forwarding Ether as required
        bool reverted = false;
        uint256 returnedTokenId = 0;
        try c.createArtFromFactory{value: sendValue}(artId) returns (uint256 t) {
            returnedTokenId = t;
        } catch {
            reverted = true;
        }

        // observe post-state
        uint256 afterCounter = c.tokenIdCounter();
        uint256 afterMapped = c.getTokenIdFromFactoryArtId(artId);
        address protocolDest = c.protocolFeeDestination();

        // General rule to assert:
        // If call did NOT revert then:
        //  - afterCounter == beforeCounter + 1
        //  - returnedTokenId equals the token id recorded for artId (nonzero)
        //  - mapping was zero before and now maps to returnedTokenId
        // If call reverted then state should be unchanged (counter unchanged and mapping unchanged)
        assert(
            reverted
            ? (afterCounter == beforeCounter && afterMapped == beforeMapped)
            : (
                afterCounter == beforeCounter + 1
                && returnedTokenId == afterMapped
                && returnedTokenId != 0
                // additionally, if some fee was expected (artCreateFee can be read), the protocol destination address must be nonzero
                && protocolDest != address(0)
            )
        );
    }

    // allow contract to receive ETH for sending in tests
    receive() external payable {}
}

