    function run(uint256 artId, uint256 sendValue) public payable {
        require(address(this).balance >= sendValue, "insufficient test balance");

        uint256 beforeCounter = c.tokenIdCounter();

        bool didRevert;
        uint256 returnedTokenId = 0;
        try c.createArtFromFactory{value: sendValue}(artId) returns (uint256 t) {
            didRevert = false;
            returnedTokenId = t;
        } catch {
            didRevert = true;
        }

        uint256 afterCounter = c.tokenIdCounter();
        uint256 mapped = c.getTokenIdFromFactoryArtId(artId);

        // If the call reverted, counter must be unchanged. Otherwise,
